// src/store/index.js
import { createStore } from "vuex";
import productStore from "./productStore"; // 引入产品模块
import userStore from "./userStore"; // 引入用户模块

// 创建 Vuex Store
const store = createStore({
  modules: {
    product: productStore, // 注册产品模块
    user: userStore, // 注册用户模块
  },
});

export default store; // 导出 Vuex Store
